import { MakeLogicType, actions, kea, listeners, path, selectors } from 'kea'
import { router } from 'kea-router'
import posthog from 'posthog-js'

import { urls } from 'scenes/urls'

export type TodayHomeTab = 'today' | 'ask' | 'canvas'

const TODAY_HOME_TABS: TodayHomeTab[] = ['today', 'ask', 'canvas']

// pinned: the `tab` search param is in links people share. Renaming a value breaks them.
export function todayHomeTabFromParam(value: unknown): TodayHomeTab {
    return TODAY_HOME_TABS.find((tab) => tab === value) ?? 'today'
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayHomeTabsLogicValues {
    tab: TodayHomeTab
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayHomeTabsLogicActions {
    pickTab: (tab: TodayHomeTab) => {
        tab: TodayHomeTab
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface todayHomeTabsLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        tab: (searchParams: Record<string, any>) => TodayHomeTab
    }
}

export type todayHomeTabsLogicType = MakeLogicType<
    todayHomeTabsLogicValues,
    todayHomeTabsLogicActions,
    Record<string, any>,
    todayHomeTabsLogicMeta
>

/** The tab the Today home page shows. It lives in the `tab` search param, so a link opens the same tab. */
export const todayHomeTabsLogic = kea<todayHomeTabsLogicType>([
    path(['scenes', 'project-homepage', 'today', 'todayHomeTabsLogic']),
    actions({
        pickTab: (tab: TodayHomeTab) => ({ tab }),
    }),
    selectors({
        tab: [
            () => [router.selectors.searchParams],
            (searchParams: Record<string, any>): TodayHomeTab => todayHomeTabFromParam(searchParams.tab),
        ],
    }),
    listeners(() => ({
        pickTab: ({ tab }) => {
            // pinned: analytics event name and properties. Renaming them breaks dashboards.
            posthog.capture('today home tab picked', { tab })
            const { tab: _previous, ...searchParams } = router.values.searchParams
            router.actions.push(urls.projectHomepage(), tab === 'today' ? searchParams : { ...searchParams, tab })
        },
    })),
])
